// Poll both retrieval suites' result rows (created since this run started).
// Partition by run_id prefix: 'agent-retrieval-' = agent suite, else workflow suite.
const expected = $('Load Cases').all().length;
const seen = new Set();
const rows = [];
for (const item of $input.all()) {
  const r = item.json;
  if (!r || !r.run_id || !r.case_id) continue;
  const key = r.run_id + '|' + r.case_id;
  if (seen.has(key)) continue;
  seen.add(key);
  rows.push(r);
}
const oldRows = rows.filter(function (r) { return String(r.run_id).indexOf('agent-retrieval-') !== 0; });
const newRows = rows.filter(function (r) { return String(r.run_id).indexOf('agent-retrieval-') === 0; });
const distCases = function (arr) { const set = new Set(); for (const r of arr) set.add(r.case_id); return set.size; };
const poll = ($runIndex || 0) + 1;
return [{ json: {
  expected: expected,
  old_run_id: oldRows.length ? oldRows[0].run_id : '',
  new_run_id: newRows.length ? newRows[0].run_id : '',
  old_landed: distCases(oldRows),
  new_landed: distCases(newRows),
  polls: poll,
  complete: distCases(oldRows) >= expected && distCases(newRows) >= expected,
  timeout: poll >= 25,
} }];

// Head-to-head retrieval comparison: workflow Darwin vs FirstClassDarwin.
const expected = $('Load Cases').all().length;
const p = $input.first().json;
const slugs = {};
for (const c of $('Load Cases').all()) slugs[c.json.id] = c.json.slug;

const rows = [];
const seen = new Set();
for (const item of $('Load Results').all()) {
  const r = item.json;
  if (!r || !r.run_id || !r.case_id) continue;
  const key = r.run_id + '|' + r.case_id;
  if (seen.has(key)) continue;
  seen.add(key);
  rows.push(r);
}
const oldRows = rows.filter(function (r) { return String(r.run_id).indexOf('agent-retrieval-') !== 0; });
const newRows = rows.filter(function (r) { return String(r.run_id).indexOf('agent-retrieval-') === 0; });

const byCase = {};
const add = function (r, side) {
  const slug = slugs[r.case_id] || r.case_slug || r.case_id;
  if (!byCase[slug]) byCase[slug] = {};
  byCase[slug][side] = r;
};
for (const r of oldRows) add(r, 'workflow');
for (const r of newRows) add(r, 'agent');

const count = function (arr, st) { return arr.filter(function (r) { return r.status === st; }).length; };
const iconOf = function (st) { return st === 'pass' ? '✅' : (st === 'fail' ? '❌' : (st === 'error' ? '💥' : '—')); };
const cell = function (t) { return String(t).replace(/|/g, '\|').replace(/
+/g, ' '); };
const fmtNum = function (v) { return (v === null || v === undefined) ? '-' : Number(v).toFixed(2); };
const metricsOf = function (r) {
  let m = r && r.metrics;
  if (typeof m === 'string') { try { m = JSON.parse(m); } catch (e) { m = null; } }
  return m || {};
};

let totalTokens = 0;
for (const r of newRows) {
  if (r.usage && typeof r.usage.totalTokens === 'number') totalTokens += r.usage.totalTokens;
}

const lines = [];
lines.push('## Retrieval head-to-head — workflow Darwin vs FirstClassDarwin', '');
lines.push('Workflow run: `' + cell(p.old_run_id || 'n/a') + '` · Agent run: `' + cell(p.new_run_id || 'n/a') + '` · ' + expected + ' cases each', '');
lines.push('| Surface | Landed | ✅ Pass | ❌ Fail | 💥 Error |');
lines.push('| --- | --- | --- | --- | --- |');
lines.push('| Workflow Darwin | ' + oldRows.length + ' | ' + count(oldRows, 'pass') + ' | ' + count(oldRows, 'fail') + ' | ' + count(oldRows, 'error') + ' |');
lines.push('| FirstClassDarwin | ' + newRows.length + ' | ' + count(newRows, 'pass') + ' | ' + count(newRows, 'fail') + ' | ' + count(newRows, 'error') + ' |');
if (totalTokens) lines.push('', 'Agent token usage: **' + totalTokens.toLocaleString() + '** total (' + newRows.length + ' cases).');
lines.push('', '### Case-by-case', '');
lines.push('| Case | Workflow | Agent | mrr wf → agent | hits wf → agent | Reason (agent) |');
lines.push('| --- | --- | --- | --- | --- | --- |');
const slugsSorted = Object.keys(byCase).sort();
let bothPass = 0;
const diffs = [];
for (const slug of slugsSorted) {
  const entry = byCase[slug];
  const wst = entry.workflow ? entry.workflow.status : 'missing';
  const ast = entry.agent ? entry.agent.status : 'missing';
  if (wst === 'pass' && ast === 'pass') bothPass += 1; else diffs.push(slug);
  const wm = metricsOf(entry.workflow);
  const am = metricsOf(entry.agent);
  const wMrr = wm.retrieval ? fmtNum(wm.retrieval.mrr) : '-';
  const aMrr = am.retrieval ? fmtNum(am.retrieval.mrr) : '-';
  const wHits = wm.retrieval_hits != null ? wm.retrieval_hits : '-';
  const aHits = am.retrieval_hits != null ? am.retrieval_hits : '-';
  const reason = am.reason && ast !== 'pass' ? cell(am.reason) : '—';
  lines.push('| `' + cell(slug) + '` | ' + iconOf(wst) + ' ' + wst + ' | ' + iconOf(ast) + ' ' + ast + ' | ' + wMrr + ' → ' + aMrr + ' | ' + wHits + ' → ' + aHits + ' | ' + reason + ' |');
}
if (diffs.length) lines.push('', '#### Status differences', '', ...diffs.map(function (sl) { return '- `' + sl + '`'; }));

const generatedAt = new Date().toISOString();
const baseUrl = $vars.instance_url || 'https://darwin-staging.app.n8n.cloud';
const executionUrl = baseUrl + '/workflow/' + (($workflow && $workflow.id) || 'retrieval-head-to-head') + '/executions/' + $execution.id;
lines.push('', '_Generated ' + generatedAt + ' · [Head-to-head execution](' + executionUrl + ')_');

const markdown = lines.join('
').replace(/
{3,}/g, '

').trimEnd() + '
';
return [{ json: {
  markdown: markdown,
  generated_at: generatedAt,
  execution_url: executionUrl,
  total_cases: expected,
  both_passed: diffs.length === 0 && bothPass === expected,
  differing_cases: diffs,
} }];

// Build Slack Block Kit markdown blocks from the Summary node's markdown output.
// Splits long text across multiple mrkdwn blocks (3,000-char limit each),
// up to ~90KB total serialized JSON payload to stay within Slack API limits.
// Splits on newlines where possible. Ported from the "Slack" workflow (9UJFDlOnoxSzFCS1).

const PER_BLOCK = 2900;  // leave margin under Slack's 3000-char limit
const MAX_BLOCKS = 50;   // hard cap: Slack max 50 blocks
const MAX_PAYLOAD_BYTES = 90000;  // ~90KB budget for serialized { blocks: [...] }
const TRUNCATION_NOTE = '

_… (truncated: response too long for a single Slack message)_';

let text = $json.markdown ?? '';
const fullText = text;  // preserve original for downstream use

// --- Helper: estimate serialized size of a blocks array ---
function estimatePayloadSize(blocksArr) {
  // Serialize just the blocks array; the outer { "blocks": [...] } wrapper adds ~15 chars
  return JSON.stringify(blocksArr).length + 20;
}

// --- Split text into chunks ---
function splitIntoChunks(str, chunkSize, maxBlocks, maxBytes) {
  const chunks = [];
  const trialBlocks = [];

  while (str.length > 0 && chunks.length < maxBlocks) {
    if (str.length <= chunkSize) {
      chunks.push(str);
      trialBlocks.push({ type: 'markdown', text: str });
      if (estimatePayloadSize(trialBlocks) > maxBytes) {
        const removed = chunks.pop();
        trialBlocks.pop();
        const remaining = maxBytes - estimatePayloadSize(trialBlocks);
        const maxTextLen = Math.max(0, remaining - 60);
        if (maxTextLen > 50) {
          chunks.push(removed.slice(0, maxTextLen) + TRUNCATION_NOTE);
        }
      }
      break;
    }

    // Try to find last newline within the chunk boundary
    const sliceTarget = str.slice(0, chunkSize);
    const lastNewline = sliceTarget.lastIndexOf('\n');
    let chunk;
    if (lastNewline > chunkSize - 500) {
      chunk = str.slice(0, lastNewline);
      str = str.slice(lastNewline + 1);
    } else {
      chunk = sliceTarget;
      str = str.slice(chunkSize);
    }

    const tentativeBlocks = [...trialBlocks, { type: 'markdown', text: chunk }];
    if (estimatePayloadSize(tentativeBlocks) > maxBytes) {
      const remaining = maxBytes - estimatePayloadSize(trialBlocks);
      const maxTextLen = Math.max(0, remaining - 60);
      if (maxTextLen > 50) {
        chunks.push(chunk.slice(0, maxTextLen) + TRUNCATION_NOTE);
      }
      break;
    }

    chunks.push(chunk);
    trialBlocks.push({ type: 'markdown', text: chunk });
  }

  if (str.length > 0 && chunks.length === maxBlocks) {
    chunks[chunks.length - 1] = chunks[chunks.length - 1].replace(/\n*$/, '') + TRUNCATION_NOTE;
  }

  return chunks;
}

const chunks = splitIntoChunks(text, PER_BLOCK, MAX_BLOCKS, MAX_PAYLOAD_BYTES);
const blocks = chunks.map(t => ({ type: 'markdown', text: t }));
const content = { blocks };

return [{ json: { blocksJson: JSON.stringify(content), output: fullText } }];

// Group the formatted blocks into message-sized chunks so no single Slack
// message exceeds Slack's cumulative block-text limit (~13k chars, undocumented —
// see slackapi/bolt-js#2509). Emits one item per message; Send a message then posts
// one message per item. Ported from the "Slack" workflow (9UJFDlOnoxSzFCS1).
const MSG_BUDGET = 8000; // chars of block text per message, safe margin under ~13k

const blocksJson = $('format').first().json.blocksJson;

let blocks;
try {
  blocks = JSON.parse(blocksJson).blocks;
  if (!Array.isArray(blocks) || blocks.length === 0) throw new Error('no blocks');
} catch (e) {
  // Fall back to previous single-message behaviour if parsing fails
  return [{ json: { blocksJson, part: 1, totalParts: 1 } }];
}

const messages = [];
let current = [];
let currentLen = 0;

for (const block of blocks) {
  const len = (block.text || '').length;
  if (current.length > 0 && currentLen + len > MSG_BUDGET) {
    messages.push(current);
    current = [];
    currentLen = 0;
  }
  current.push(block);
  currentLen += len;
}
if (current.length > 0) messages.push(current);

return messages.map((msgBlocks, i) => ({
  json: {
    blocksJson: JSON.stringify({ blocks: msgBlocks }),
    part: i + 1,
    totalParts: messages.length,
  },
}));
